var i=[{title:`Was du reduzieren solltest`,text:`Der einfachste Ansatz ist, für mehrere Einheiten weniger harte Sätze zu machen und weiter vom Muskelversagen entfernt zu bleiben. Wenn du zum Beispiel normalerweise vier Sätze pro Übung machst, kannst du eine Woche lang je zwei leichte Sätze machen. Den Umfang um etwa 40–50 % zu senken ist eine praktische Option. Die Wissenschaft legt keinen genauen Prozentsatz fest.`},{title:`Etwas Trainingsreiz behalten`,text:`Ein Deload kann trotzdem Training enthalten. Vertraute Übungen mit geringerer Anstrengung halten Koordination und Routine am Laufen. Manche Heber behalten moderate Lasten und machen weniger Sätze. Andere senken Last und Sätze, wenn ihre Gelenke oder die allgemeine Ermüdung das Problem sind. Die beste Wahl hängt davon ab, warum du den Deload brauchst.`},{title:`Wann er hilft`,text:`Warnzeichen können mehrere ungewöhnlich harte Trainings, sinkende Leistung, Ermüdung, die nicht verschwindet, oder ein wachsendes Gefühl sein, dass du dich nicht erholst. Diese Zeichen haben viele mögliche Ursachen. Tue Krankheit oder medizinische Symptome nicht als normale Trainingsermüdung ab. Wenn du neu im Training bist, brauchst du vielleicht einfach einen leichteren regulären Plan ohne geplante Deloads.`},{title:`Geplant oder nach Bedarf`,text:`Manche strukturierten Programme nutzen alle vier bis acht Wochen eine leichtere Woche, besonders bei hoher Belastung. Dieser Zeitpunkt ist ein Weg, die Dinge zu organisieren. Wenn ein moderates Programm für dich gut läuft, brauchst du möglicherweise keinen formalen Deload, und wenn du ungewöhnlichem Stress ausgesetzt bist, kann ein früherer helfen.`},{title:`TrainUp nutzen`,text:`Woche 4 jedes TrainUp-Plans ist eine leichtere Deload-Woche. Wenn du deinen Plan neu erstellst, wird er leichter, wenn 2 deiner letzten 3 Trainings sehr hart (RPE 9 oder mehr) oder zu weniger als 60 % abgeschlossen waren. Kehre nach einer leichteren Phase Schritt für Schritt zu normalen Lasten zurück und beobachte, wie du reagierst. Eine Woche Pause garantiert nicht, dass du stärker zurückkommst.`}];var t=[{label:`ACSM-Positionspapier 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: Sicherheit und Grundlagen des Krafttrainings`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Systematische Übersichtsarbeit zu Periodisierung und Trainingsergebnissen`,url:`https://pubmed.ncbi.nlm.nih.gov/35044672/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};